import React, { useState, useEffect } from 'react';
import {
  Typography, Paper, Button, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, IconButton, Dialog,
  DialogTitle, DialogContent, DialogActions, TextField, Box,
  Alert, FormControl, InputLabel, Select, MenuItem, Chip,
  Grid, Checkbox, List, ListItem, ListItemText, ListItemSecondaryAction,
  Tabs, Tab, Divider, Autocomplete, Stack
} from '@mui/material';
import { 
  Add, Edit, Delete, SupervisorAccount, 
  Engineering, Category, People 
} from '@mui/icons-material';
import { realChecklistService } from '../../services/realApiService';
import api from '../../services/api';

const UsersManagement = () => {
  const [users, setUsers] = useState([]);
  const [areas, setAreas] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [openSupervisorDialog, setOpenSupervisorDialog] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [selectedSupervisor, setSelectedSupervisor] = useState(null);
  const [newUser, setNewUser] = useState({ 
    username: '', 
    password: '',
    name: '', 
    role: 'operator', 
    areas: [],
    is_active: true
  });
  const [selectedAreas, setSelectedAreas] = useState([]);
  const [availableOperators, setAvailableOperators] = useState([]);
  const [selectedOperators, setSelectedOperators] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [dialogTab, setDialogTab] = useState(0);

  // Cargar usuarios, áreas y detalles
  const loadData = async () => {
    try {
      setLoading(true);
      const [usersResponse, areasResponse] = await Promise.all([
        realChecklistService.getUsers(),
        realChecklistService.getAreas()
      ]);

      if (usersResponse.data.success) {
        // Para cada usuario, cargar sus áreas
        const usersWithDetails = await Promise.all(
          usersResponse.data.users.map(async (user) => {
            try {
              const detailsResponse = await api.get(`/api/user-advanced/${user.id}/details`);
              if (detailsResponse.data.success) {
                return { ...user, areas: detailsResponse.data.user.areas || [] };
              }
            } catch (error) {
              console.error(`Error cargando detalles usuario ${user.id}:`, error);
            }
            return { ...user, areas: [] };
          })
        );
        setUsers(usersWithDetails);
      }
      
      if (areasResponse.data.success) {
        setAreas(areasResponse.data.areas.map(a => a.name));
      }
    } catch (error) {
      setError('Error cargando datos: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateUser = async () => {
    try {
      if (!newUser.username || !newUser.password || !newUser.name) {
        setError('Usuario, contraseña y nombre son obligatorios');
        return;
      }

      // Crear usuario básico
      const userData = {
        username: newUser.username,
        password: newUser.password,
        name: newUser.name,
        role: newUser.role,
        is_active: newUser.is_active
      };

      const response = await realChecklistService.createUser(userData);
      if (response.data.success) {
        const userId = response.data.user.id;
        
        // Asignar áreas si hay
        if (selectedAreas.length > 0) {
          await api.put(`/api/user-advanced/${userId}/areas`, { areas: selectedAreas });
        }
        
        await loadData();
        setOpenDialog(false);
        resetForm();
        setError('');
      }
    } catch (error) {
      setError('Error creando usuario: ' + error.message);
    }
  };

  const handleUpdateUser = async () => {
    try {
      const userData = {
        username: newUser.username,
        name: newUser.name,
        role: newUser.role,
        is_active: newUser.is_active
      };

      // Si hay nueva contraseña, agregarla
      if (newUser.password) {
        userData.password = newUser.password;
      }

      const response = await realChecklistService.updateUser(editingUser.id, userData);
      if (response.data.success) {
        // Actualizar áreas
        await api.put(`/api/user-advanced/${editingUser.id}/areas`, { areas: selectedAreas });
        
        await loadData();
        setOpenDialog(false);
        resetForm();
        setError('');
      }
    } catch (error) {
      setError('Error actualizando usuario: ' + error.message);
    }
  };

  const handleManageSupervisor = async (user) => {
    setSelectedSupervisor(user);
    try {
      // Cargar operadores disponibles
      const response = await api.get(`/api/user-advanced/supervisor/${user.id}/available-operators`);
      if (response.data.success) {
        setAvailableOperators(response.data.operators);
      }
      
      // Cargar operadores actualmente asignados
      const detailsResponse = await api.get(`/api/user-advanced/${user.id}/details`);
      if (detailsResponse.data.success && detailsResponse.data.user.operators) {
        setSelectedOperators(detailsResponse.data.user.operators.map(op => op.id));
      }
      
      setOpenSupervisorDialog(true);
    } catch (error) {
      setError('Error cargando operadores: ' + error.message);
    }
  };

  const handleAssignOperators = async () => {
    try {
      const response = await api.put(
        `/api/user-advanced/supervisor/${selectedSupervisor.id}/operators`,
        { operatorIds: selectedOperators }
      );
      
      if (response.data.success) {
        await loadData();
        setOpenSupervisorDialog(false);
        setSelectedSupervisor(null);
        setSelectedOperators([]);
        setError('');
        alert(`Operadores asignados correctamente: ${response.data.assignedCount}`);
      }
    } catch (error) {
      setError('Error asignando operadores: ' + error.message);
    }
  };

  const handleEditUser = (user) => {
    setEditingUser(user);
    setNewUser({ 
      username: user.username,
      password: '',
      name: user.name, 
      role: user.role, 
      is_active: user.is_active
    });
    setSelectedAreas(user.areas || []);
    setOpenDialog(true);
    setDialogTab(0);
  };

  const handleSave = () => {
    if (editingUser) {
      handleUpdateUser();
    } else {
      handleCreateUser();
    }
  };

  const resetForm = () => {
    setEditingUser(null);
    setNewUser({ 
      username: '', 
      password: '',
      name: '', 
      role: 'operator', 
      areas: [],
      is_active: true
    });
    setSelectedAreas([]);
    setSelectedOperators([]);
  };

  const roles = [
    { value: 'admin', label: 'Administrador', icon: <People /> },
    { value: 'supervisor', label: 'Supervisor', icon: <SupervisorAccount /> },
    { value: 'operator', label: 'Operador', icon: <Engineering /> }
  ];

  const getRoleColor = (role) => {
    switch(role) {
      case 'admin': return 'error';
      case 'supervisor': return 'warning';
      case 'operator': return 'success';
      default: return 'default';
    }
  };

  const renderAreasChips = (userAreas) => {
    if (!userAreas || userAreas.length === 0) {
      return <Chip label="Sin áreas" size="small" variant="outlined" />;
    }
    
    return (
      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
        {userAreas.slice(0, 2).map((area, index) => (
          <Chip key={index} label={area} size="small" />
        ))}
        {userAreas.length > 2 && (
          <Chip label={`+${userAreas.length - 2}`} size="small" variant="outlined" />
        )}
      </Box>
    );
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Usuarios
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            resetForm();
            setOpenDialog(true);
          }}
        >
          Nuevo Usuario
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Usuario</TableCell>
              <TableCell>Nombre</TableCell>
              <TableCell>Rol</TableCell>
              <TableCell>Áreas Asignadas</TableCell>
              <TableCell>Estado</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  Cargando usuarios...
                </TableCell>
              </TableRow>
            ) : users.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  No hay usuarios registrados.
                </TableCell>
              </TableRow>
            ) : (
              users.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.username}</TableCell>
                  <TableCell>{user.name}</TableCell>
                  <TableCell>
                    <Chip 
                      label={user.role} 
                      color={getRoleColor(user.role)}
                      size="small"
                      icon={roles.find(r => r.value === user.role)?.icon}
                    />
                  </TableCell>
                  <TableCell>
                    {renderAreasChips(user.areas)}
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={user.is_active ? 'Activo' : 'Inactivo'} 
                      color={user.is_active ? 'success' : 'error'}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton 
                      color="primary"
                      onClick={() => handleEditUser(user)}
                      title="Editar"
                      size="small"
                    >
                      <Edit fontSize="small" />
                    </IconButton>
                    
                    {user.role === 'supervisor' && (
                      <IconButton 
                        color="secondary"
                        onClick={() => handleManageSupervisor(user)}
                        title="Gestionar Operadores"
                        size="small"
                      >
                        <People fontSize="small" />
                      </IconButton>
                    )}
                    
                    <IconButton 
                      color="error"
                      onClick={() => {
                        if (window.confirm(`¿Eliminar usuario ${user.name}?`)) {
                          realChecklistService.deleteUser(user.id).then(loadData);
                        }
                      }}
                      title="Eliminar"
                      size="small"
                    >
                      <Delete fontSize="small" />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Diálogo para crear/editar usuario */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          {editingUser ? 'Editar Usuario' : 'Crear Nuevo Usuario'}
        </DialogTitle>
        
        <Tabs value={dialogTab} onChange={(e, v) => setDialogTab(v)} sx={{ px: 3 }}>
          <Tab label="Información Básica" />
          <Tab label="Asignación de Áreas" />
        </Tabs>
        
        <DialogContent>
          {dialogTab === 0 ? (
            <Grid container spacing={2} sx={{ mt: 1 }}>
              <Grid item xs={12} sm={6}>
                <TextField
                  autoFocus
                  margin="dense"
                  label="Usuario (login)"
                  fullWidth
                  value={newUser.username}
                  onChange={(e) => setNewUser(prev => ({ ...prev, username: e.target.value }))}
                  required
                  disabled={!!editingUser}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  margin="dense"
                  label={editingUser ? 'Nueva Contraseña' : 'Contraseña'}
                  type="password"
                  fullWidth
                  value={newUser.password}
                  onChange={(e) => setNewUser(prev => ({ ...prev, password: e.target.value }))}
                  required={!editingUser}
                />
              </Grid>
              
              <Grid item xs={12}>
                <TextField
                  margin="dense"
                  label="Nombre Completo"
                  fullWidth
                  value={newUser.name}
                  onChange={(e) => setNewUser(prev => ({ ...prev, name: e.target.value }))}
                  required
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Rol</InputLabel>
                  <Select
                    value={newUser.role}
                    label="Rol"
                    onChange={(e) => setNewUser(prev => ({ ...prev, role: e.target.value }))}
                  >
                    {roles.map(role => (
                      <MenuItem key={role.value} value={role.value}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {role.icon}
                          {role.label}
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              
              <Grid item xs={12} sm={6}>
                {editingUser && (
                  <FormControl fullWidth>
                    <InputLabel>Estado</InputLabel>
                    <Select
                      value={newUser.is_active}
                      label="Estado"
                      onChange={(e) => setNewUser(prev => ({ ...prev, is_active: e.target.value }))}
                    >
                      <MenuItem value={true}>Activo</MenuItem>
                      <MenuItem value={false}>Inactivo</MenuItem>
                    </Select>
                  </FormControl>
                )}
              </Grid>
            </Grid>
          ) : (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2" gutterBottom>
                Selecciona las áreas para este usuario:
              </Typography>
              <FormControl fullWidth>
                <Autocomplete
                  multiple
                  options={areas}
                  value={selectedAreas}
                  onChange={(event, newValue) => setSelectedAreas(newValue)}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      variant="outlined"
                      placeholder="Selecciona áreas"
                    />
                  )}
                  renderTags={(value, getTagProps) =>
                    value.map((option, index) => (
                      <Chip
                        label={option}
                        size="small"
                        {...getTagProps({ index })}
                      />
                    ))
                  }
                />
              </FormControl>
              <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block' }}>
                {selectedAreas.length} área(s) seleccionada(s)
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancelar</Button>
          {dialogTab === 0 ? (
            <Button onClick={() => setDialogTab(1)} variant="outlined">
              Siguiente: Áreas
            </Button>
          ) : (
            <Button onClick={() => setDialogTab(0)} variant="outlined">
              Anterior: Información
            </Button>
          )}
          <Button 
            onClick={handleSave} 
            variant="contained"
            disabled={(!editingUser && (!newUser.username || !newUser.password || !newUser.name))}
          >
            {editingUser ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo para gestionar operadores de supervisor */}
      <Dialog open={openSupervisorDialog} onClose={() => setOpenSupervisorDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <SupervisorAccount />
            Gestionar Operadores del Supervisor: {selectedSupervisor?.name}
          </Box>
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" paragraph>
            Selecciona los operadores que serán supervisados por {selectedSupervisor?.name}
          </Typography>
          
          <List dense sx={{ maxHeight: 400, overflow: 'auto' }}>
            {availableOperators.map((operator) => (
              <ListItem key={operator.id} divider>
                <Checkbox
                  edge="start"
                  checked={selectedOperators.includes(operator.id)}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setSelectedOperators([...selectedOperators, operator.id]);
                    } else {
                      setSelectedOperators(selectedOperators.filter(id => id !== operator.id));
                    }
                  }}
                />
                <ListItemText
                  primary={operator.name}
                  secondary={`Usuario: ${operator.username} | Áreas: ${operator.areas?.join(', ') || 'Ninguna'}`}
                />
                <Chip 
                  label={operator.is_active ? 'Activo' : 'Inactivo'} 
                  size="small"
                  color={operator.is_active ? 'success' : 'default'}
                />
              </ListItem>
            ))}
          </List>
          
          {availableOperators.length === 0 && (
            <Typography align="center" color="textSecondary" sx={{ py: 3 }}>
              No hay operadores disponibles para asignar
            </Typography>
          )}
          
          <Divider sx={{ my: 2 }} />
          
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="body2">
              Operadores seleccionados: <strong>{selectedOperators.length}</strong>
            </Typography>
            <Button 
              size="small" 
              onClick={() => setSelectedOperators([])}
              disabled={selectedOperators.length === 0}
            >
              Limpiar selección
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSupervisorDialog(false)}>Cancelar</Button>
          <Button 
            onClick={handleAssignOperators} 
            variant="contained"
            disabled={selectedOperators.length === 0}
          >
            Asignar Operadores
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default UsersManagement;
